"""Publish compact frozen-model challenge results without modifying prior results."""
import json
from pathlib import Path
import numpy as np
from sklearn.metrics import accuracy_score,f1_score
ROOT=Path(__file__).resolve().parents[1];p=ROOT/'results/independent';s=json.loads((p/'summary.json').read_text());raw=json.loads((p/'study.json').read_text())
rows=[]
for name in sorted({r['case'] for r in raw['runs']}):
 runs=[r for r in raw['runs'] if r['case']==name];y=sum([r['truth'] for r in runs],[]);pred=sum([r['predictions'] for r in runs],[]);scores=sum([r['attack_scores'] for r in runs],[]);elig=sum([r['block_eligible'] for r in runs],[])
 rows.append({'case':name,'runs':len(runs),'rows':len(y),'accuracy':accuracy_score(y,pred),'supported_class_macro_f1':f1_score(y,pred,labels=sorted(set(y)),average='macro',zero_division=0),'binary_attack_recall':float(np.mean([v>=.5 for v,t in zip(scores,y) if t!='BENIGN'])) if any(t!='BENIGN' for t in y) else None,'benign_block_eligibility':float(np.mean([v for v,t in zip(elig,y) if t=='BENIGN']))})
s.update(cases=rows,frozen_hashes=raw['frozen_hashes'],generator_sha256=raw['generator_sha256'],unlabelled_or_ambiguous_flows=sum(r['unlabelled_or_ambiguous_flows'] for r in raw['runs']),capture_limited_runs=sum(bool(r['capture_limited']) for r in raw['runs']),packets=sum(r['packets'] for r in raw['runs']),scope=raw['note'])
(ROOT/'docs/INDEPENDENT_CHALLENGE_SUMMARY.json').write_text(json.dumps(s,indent=2))
a=s['results']['None'];lines=['# Frozen model challenge study','', '5 November 2026','', '## Result','',f"The frozen recommended model failed to generalize reliably to the new controlled generators and mixed traffic. Across {s['runs']} runs and {a['rows']} labelled observed flow records, argmax macro F1 was {a['argmax_macro_f1']:.4f}, selective-policy macro F1 was {a['policy_macro_f1']:.4f}, coverage was {a['coverage']:.2%}, and benign blocking eligibility was {a['benign_block_eligibility']:.2%}. Enforcement was disabled; eligibility is not actual blocking.",'', '## Protocol','',raw['note'],'','Two endpoint rotations, five cases and 0%/10% random link loss yielded twenty captures. Independent socket clients and a new HTTP/UDP service replaced the training generator. Benign UDP without replies, responding attack-load UDP, legitimate successful/failed logins, password guessing and random port probes ran with simultaneous background traffic. Configured request rates differed from collection settings. UDP sizes and packet counts varied. Ground truth was assigned using sender socket logs, not the capture scenario label. All observed packets contributed to context; unknown or ambiguous flows were excluded and counted.','', 'The joblib and metadata SHA256 hashes were frozen before collection and checked unchanged afterward. No fitting, threshold adjustment or model choice used the challenge results. Existing prepared training datasets were not modified. Classifier performance was evaluated offline on actual destination captures using the same extractor and saved model. This does not test online decision or enforcement latency.','', '## Cases','', '| Case | Observed labelled flows | Accuracy | Binary attack recall | Benign block eligibility |','|---|---:|---:|---:|---:|']
for r in rows:lines.append(f"| {r['case']} | {r['rows']} | {r['accuracy']:.2%} | "+('N/A' if r['binary_attack_recall'] is None else f"{r['binary_attack_recall']:.2%}")+f" | {r['benign_block_eligibility']:.2%} |")
lines+=['','## Interpretation and limits','','These results contradict any claim that the earlier near-perfect score establishes robustness to changed traffic generation or mixtures. They support the audit concern about generator and context shortcuts. They do not identify a single causal feature: service, traffic mix and generation all changed. The model remains a demonstrator for its original scenarios; it is not validated as a robust detector. New failures should remain an untouched challenge set for this frozen model. If used to improve a later model, a further independent test is required.','','The workload labels describe intended benign/attack roles. Low bounded load is not evidence of actual denial of service, and traffic statistics alone cannot infer intent. Similar legitimate and malicious login traffic may be intrinsically difficult to distinguish from a ten-packet prefix. Source workloads share the same four guests and private network. This is not an independent network, public dataset or realistic Internet-scale validation. Zero missed capture flags does not prove zero kernel capture loss. Scores are conditional on emitted labelled flows, not end-to-end recall of completely invisible flows. Related flows are correlated; two endpoint rotations do not yield broad confidence intervals. Requested 10% loss is not assumed to equal achieved loss; source qdisc counters are retained in raw study records.','','## Evidence and reproduction','',f"Captured packets: {s['packets']}; excluded unlabelled/ambiguous flows: {s['unlabelled_or_ambiguous_flows']}; capture-limited flags: {s['capture_limited_runs']}.",'','Run `.venv/bin/python -m scripts.independent_study`, then `.venv/bin/python -m scripts.summarize_independent`. The live driver needs all four provisioned VMs and must run without another experiment controlling them. It resets temporary NetEm settings and stops its temporary servers in cleanup. Raw source logs, captures, hashes, predictions and qdisc counters remain in `results/independent`; the compact public summary is `docs/INDEPENDENT_CHALLENGE_SUMMARY.json`.']
(ROOT/'docs/INDEPENDENT_CHALLENGE.md').write_text('\n'.join(lines)+'\n');print('\n'.join(lines[:8]))
